Bash(# Find all dynamic route directories and group by parent
find app -type d -name '\[*\]' | while read dir; do
    parent=$(dirname "$dir")
    param=$(basename "$dir" | tr -d '[]')
    echo "$parent:$param"
done | sort | awk -F: '
{
    if ($1 == prev_parent && $2 != prev_param) {
        print "CONFLICT in " $1 ": [" prev_param "] vs [" $2 "]"
    }
    prev_parent = $1
    prev_param = $2
}')
